async function cancelOrder(args, inputResponses) {
  await payments.refund(args.orderId);            // side effect
  if (!inputResponses?.confirm) {
    return { resultType: "input_required",
             inputRequests: [{ name: "confirm",
               message: `Cancel order ${args.orderId}?` }] };
  }
  await orders.cancel(args.orderId);
  return { content: [{ type: "text", text: "Cancelled" }] };
}
